// Webhook de Chatwoot: solo interesan los mensajes ENTRANTES (respuestas de los usuarios)
const b = $json.body || {};
if (b.event !== 'message_created' || b.message_type !== 'incoming' || b.private) return [];

const sender = b.sender || b.conversation?.meta?.sender || {};
const telefono = String(sender.phone_number || '').replace(/\D/g, '');
if (!telefono) return [];

// created_at puede venir como fecha ISO o como segundos UNIX
let fecha = b.created_at;
if (typeof fecha === 'number' || /^\d+$/.test(String(fecha))) fecha = new Date(Number(fecha) * 1000).toISOString();
if (!fecha || isNaN(new Date(fecha))) fecha = new Date().toISOString();

// Los botones de la plantilla llegan como texto ("Dejar de recibir") con in_reply_to = id del mensaje de la alerta
const inReplyTo = b.content_attributes?.in_reply_to;
return [{ json: {
  telefono, fecha, contact_id: sender.id ? String(sender.id) : '',
  contenido: String(b.content || '').slice(0, 500),
  in_reply_to: inReplyTo ? String(inReplyTo) : '',
} }];

// Una consulta a Chatwoot por conversación con mensajes pendientes de confirmar
const cfg = $('Configuración').first().json.cfg;
const base = `${String(cfg.chatwoot_url_publica || '').replace(/\/+$/, '')}/api/v1/accounts/${cfg.chatwoot_account_id}`;
return $('Mensajes pendientes').all()
  .filter((i) => i.json.conversation_id)
  .map((i) => ({
    json: {
      conversation_id: i.json.conversation_id,
      message_ids: (i.json.message_ids || []).map(Number),
      url: `${base}/conversations/${i.json.conversation_id}/messages`,
    },
  }));

// Extrae el estado actual (delivered / read / failed) de los mensajes que seguimos
const pedidos = $('Armar consultas').all();
const salida = [];
$input.all().forEach((item, i) => {
  const ids = new Set(pedidos[i]?.json.message_ids || []);
  for (const m of item.json.payload || []) {
    if (!ids.has(Number(m.id))) continue;
    const estado = String(m.status || '');
    if (!['delivered', 'read', 'failed'].includes(estado)) continue;
    const err = m.content_attributes?.external_error || '';
    salida.push({ json: { message_id: String(m.id), estado, error: String(err).slice(0, 300) } });
  }
});
return salida;

// "Dejar de recibir", "⛈️ Solo lluvias fuertes" y "ALTA" (botones/textos de la plantilla de alertas): se confirma
const TEXTOS = {
  // cliente: se le ofrece quedarse solo con las lluvias fuertes
  desactivado: {
    contenido: '✅ Listo, ya no recibirás avisos de IAgro.\n\nSi prefieres enterarte solo cuando vengan **lluvias fuertes o tormentas**, toca el botón. Para volver a todo, escribe **ALTA**. ¡Buena cosecha! 🌾',
    content_type: 'input_select', content_attributes: { items: [{ title: '⛈️ Lluvias fuertes', value: 'lluvias fuertes' }] },
  },
  fuertes: { contenido: '👍 Hecho. Solo te avisaremos de lluvias fuertes o tormentas.' },
  reactivado: { contenido: '🌧️ ¡Listo! Volverás a recibir los avisos de lluvia de IAgro.' },
  // contacto de una difusión que no es cliente
  baja_contacto: { contenido: '✅ Listo, ya no te enviaremos mensajes de IAgro.\n\nSi cambias de idea, escribe **ALTA**. ¡Buena cosecha! 🌾' },
  alta_contacto: { contenido: '🌧️ ¡Listo! Volverás a recibir los avisos de IAgro.' },
};
const entradas = $('Solo mensajes entrantes').all();
return $input.all().flatMap((item, i) => {
  const r = item.json.r || {};
  const e = entradas[i]?.json;
  const t = TEXTOS[r.accion];
  if (!t || !e) return [];
  return [{ json: {
    usuario_id: r.usuario_id, telefono: e.telefono, nombre: '',
    chatwoot_contact_id: e.contact_id || null,
    contenido: t.contenido, usar_plantilla: false,   // acaba de escribir: ventana de 24 h abierta
    ...(t.content_type ? { content_type: t.content_type, content_attributes: t.content_attributes } : {}),
  } }];
});
